public class LuceneSailTest extends AbstractGenericLuceneTest {

	private LuceneIndex index;

	@Override
	protected void configure(LuceneSail sail) throws IOException {
		index = new LuceneIndex(new ByteBuffersDirectory(), new StandardAnalyzer());
		sail.setLuceneIndex(index);
	}

	@Test
	public void testIndexSettings() {
		assertNotNull(index);
		// Give the thread some time to start
		try {
			Thread.sleep(100);
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
		}
		// Make sure the thread for periodic fsync is NOT running
		var allThreads = Thread.getAllStackTraces().keySet();
		assertThat(allThreads.stream().filter(t -> t.getName().startsWith("rdf4j-lucene-fsync-")).count())
				.isEqualTo(0);
	}

	@Test
	public void clearsSafeScopesForLuceneBindingSetAssignmentsInsideUnion() {
		CapturedQuery actual = evaluateAndCapturePlan(luceneUnionQuery(
				"BIND(STR(?m) AS ?source)",
				"BIND(STR(?m) AS ?source)"));

		assertThat(actual.rows()).containsExactlyInAnyOrder(
				luceneRow(SUBJECT_1, PREDICATE_1, "one", "one"),
				luceneRow(SUBJECT_1, PREDICATE_2, "one", "one"),
				luceneRow(SUBJECT_2, PREDICATE_1, "one", "one"),
				luceneRow(SUBJECT_2, PREDICATE_2, "one", "one"),
				luceneRow(SUBJECT_1, PREDICATE_1, "two", "two"),
				luceneRow(SUBJECT_1, PREDICATE_2, "two", "two"));

		String unionPlan = unionPlan(actual.optimizedPlan());
		assertThat(unionPlan.lines().filter(line -> line.strip().equals("Union (new scope)")).count()).isZero();
		assertThat(unionPlan.lines().filter(line -> line.strip().equals("Filter (new scope)")).count()).isZero();
		assertThat(unionPlan.lines().filter(line -> line.strip().equals("Filter")).count()).isEqualTo(2L);
		assertThat(unionPlan.lines()
				.filter(line -> line
						.contains("BindingSetAssignment (org.eclipse.rdf4j.sail.lucene.BindingSetCollection"))
				.count()).isEqualTo(2L);
		assertThat(unionPlan.lines().filter(line -> line.strip().endsWith("Extension")).count()).isEqualTo(2L);
	}

	@Test
	public void preservesLuceneUnionScopeForExternalDependentBranchBind() {
		CapturedQuery actual = evaluateAndCapturePlan(luceneUnionQuery(
				"BIND(BOUND(?pMatch) AS ?source)",
				"BIND(false AS ?source)"));

		assertThat(actual.rows()).containsExactlyInAnyOrder(
				luceneRow(SUBJECT_1, PREDICATE_1, "one", false),
				luceneRow(SUBJECT_1, PREDICATE_2, "one", false),
				luceneRow(SUBJECT_2, PREDICATE_1, "one", false),
				luceneRow(SUBJECT_2, PREDICATE_2, "one", false),
				luceneRow(SUBJECT_1, PREDICATE_1, "two", false),
				luceneRow(SUBJECT_1, PREDICATE_2, "two", false));

		String unionPlan = unionPlan(actual.optimizedPlan());
		assertThat(unionPlan.lines().filter(line -> line.strip().equals("Union (new scope)")).count()).isEqualTo(1L);
		assertThat(unionPlan.lines().filter(line -> line.strip().equals("Filter (new scope)")).count()).isEqualTo(2L);
	}

	private CapturedQuery evaluateAndCapturePlan(String queryString) {
		sleepAfterCommitIfNeeded();
		Logger luceneLogger = (Logger) LoggerFactory.getLogger(LuceneSailConnection.class);
		Level previousLevel = luceneLogger.getLevel();
		ListAppender<ILoggingEvent> optimizedPlanAppender = new ListAppender<>();
		optimizedPlanAppender.setContext(luceneLogger.getLoggerContext());
		optimizedPlanAppender.start();
		luceneLogger.addAppender(optimizedPlanAppender);
		luceneLogger.setLevel(Level.TRACE);

		try {
			TupleQuery query = connection.prepareTupleQuery(queryString);
			List<List<Value>> actual = new ArrayList<>();
			try (TupleQueryResult result = query.evaluate()) {
				while (result.hasNext()) {
					var bindingSet = result.next();
					actual.add(List.of(
							bindingSet.getValue("subj"),
							bindingSet.getValue("pMatch"),
							bindingSet.getValue("m"),
							bindingSet.getValue("source")));
				}
			}

			String optimizedPlan = optimizedPlanAppender.list.stream()
					.map(ILoggingEvent::getFormattedMessage)
					.filter(message -> message.startsWith("Optimized query model:"))
					.findFirst()
					.orElseThrow(() -> new AssertionError("Lucene optimized query plan was not traced"));
			return new CapturedQuery(actual, optimizedPlan);
		} finally {
			luceneLogger.detachAppender(optimizedPlanAppender);
			luceneLogger.setLevel(previousLevel);
			optimizedPlanAppender.stop();
		}
	}

	private static String luceneUnionQuery(String leftBind, String rightBind) {
		return """
				PREFIX search: <http://www.openrdf.org/contrib/lucenesail#>
				SELECT ?subj ?pMatch ?m ?source WHERE {
				  VALUES ?pMatch { <urn:predicate1> <urn:predicate2> }
				  {
				    {
				      ?subj search:matches [
				        search:query "one";
				        search:property <urn:predicate1>;
				        search:score ?score
				      ] .
				      ?subj <urn:predicate1> ?m .
				      FILTER (STR(?m) = "one")
				      %s
				    }
				    UNION
				    {
				      ?subj search:matches [
				        search:query "two";
				        search:property <urn:predicate2>;
				        search:score ?score
				      ] .
				      ?subj <urn:predicate2> ?m .
				      FILTER (STR(?m) = "two")
				      %s
				    }
				  }
				}
				""".formatted(leftBind, rightBind);
	}

	private static List<Value> luceneRow(Value subject, Value pMatch, String match, String source) {
		return List.of(subject, pMatch, vf.createLiteral(match), vf.createLiteral(source));
	}

	private static List<Value> luceneRow(Value subject, Value pMatch, String match, boolean source) {
		return List.of(subject, pMatch, vf.createLiteral(match), vf.createLiteral(source));
	}

	private static String unionPlan(String optimizedPlan) {
		String[] lines = optimizedPlan.split("\\R");
		int unionIndex = -1;
		int unionIndent = -1;
		for (int i = 0; i < lines.length; i++) {
			if (lines[i].stripLeading().startsWith("Union")) {
				unionIndex = i;
				unionIndent = lines[i].length() - lines[i].stripLeading().length();
				break;
			}
		}
		assertThat(unionIndex).isGreaterThanOrEqualTo(0);
		StringBuilder subtree = new StringBuilder();
		for (int i = unionIndex; i < lines.length; i++) {
			String line = lines[i];
			int indent = line.length() - line.stripLeading().length();
			if (i > unionIndex && !line.isBlank() && indent <= unionIndent) {
				break;
			}
			if (!subtree.isEmpty()) {
				subtree.append(System.lineSeparator());
			}
			subtree.append(line);
		}
		return subtree.toString();
	}

	private record CapturedQuery(List<List<Value>> rows, String optimizedPlan) {
	}
}
